import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"Matrix-Game: Interactive World Foundation Model","description":"","frontmatter":{"title":"Matrix-Game: Interactive World Foundation Model","arxiv":"2506.18701","date":"2025-06-23","authors":"Yifan Zhang, Chunli Peng, Boyang Wang, Puyi Wang, Qingcheng Zhu, Fei Kang, Biao Jiang, Zedong Gao, Eric Li, Yang Liu, Yahui Zhou","categories":"cs.CV, cs.AI","topics":"世界模型, 交互式视频生成, 游戏世界建模","outline":[2,2]},"headers":[],"relativePath":"papers/2506.18701.md","filePath":"papers/2506.18701.md","lastUpdated":null}'),e={name:"papers/2506.18701.md"};function l(i,s,r,m,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="matrix-game-interactive-world-foundation-model" tabindex="-1">Matrix-Game: Interactive World Foundation Model <a class="header-anchor" href="#matrix-game-interactive-world-foundation-model" aria-label="Permalink to &quot;Matrix-Game: Interactive World Foundation Model&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2506.18701" target="_blank" rel="noreferrer">2506.18701</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-06-23</td></tr><tr><td><strong>作者</strong></td><td>Yifan Zhang, Chunli Peng, Boyang Wang, Puyi Wang, Qingcheng Zhu, Fei Kang, Biao Jiang, Zedong Gao, Eric Li, Yang Liu, Yahui Zhou</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>把「无标注海量游戏视频预训练 + 动作标注数据微调」做成两阶段配方，训出 17B 的图生世界 DiT，并配套 GameWorld Score 把可控性与物理一致性变成可量化指标。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/world-models">世界模型</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>论文要解决的是「交互式世界模型」这件事在工程上一直没被打通的三个环节：动作标注数据稀缺、控制信号跟不上、以及没有统一评测。视频扩散模型这几年已经能生成视觉上很漂亮的片段，但要把它当成一个可以被 agent 操纵的环境用，就必须满足一个更苛刻的条件——用户按一下 W，画面必须真的往前走；把镜头左转再转回来，原来的场景必须还在。这两件事恰恰是纯视觉指标测不出来的。</p><p>作者选择 Minecraft 作为载体，理由很实际：biome 种类多、交互语义清晰、可以脚本化地大规模采集带动作标签的轨迹。价值在于，如果一个模型能从单张参考图出发、按键盘鼠标持续 rollout 出物理上说得通的世界，那它就同时是游戏引擎、agent 训练环境和具身规划的仿真器。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>论文点名的直接对手是两个开源 Minecraft 世界模型：OASIS 和 MineWorld，此外还讨论了 Genie / Genie 2、GameNGen、DIAMOND、GameGen-X、GameFactory、The Matrix、WorldMem。这些工作已经证明了「diffusion 可以当实时游戏引擎」这个 claim 是成立的。作者给出的批评相当具体：一类方法（GameGen-X、OASIS、WorldMem）过拟合到特定游戏数据集，跨场景泛化差；另一类（The Matrix、Genie 2、GameFactory、MineWorld）虽然在控制泛化上更进一步，但受限于模型容量与数据规模，难以真正吃透物理规则。</p><p>控制这条线上，Direct-a-Video 只能给 yaw/pitch/zoom 三个粗粒度属性；CameraCtrl 和 MotionCtrl 做到了轨迹级的连续相机控制，但它们的对象是「拍摄视角」而不是「玩家动作」，没有离散按键这一层语义。评测这条线上，VBench 测的是视觉质量与文本对齐，WorldScore 进了一步测文本条件下的 3D/4D 世界生成，两者都没有为逐帧动作条件设计的指标——这解释了为什么「可控性」长期只能靠贴视频给人看。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>站在 2025 年中，可用的线索是清楚的。第一，HunyuanVideo / Wan 这类 I2V 基座已经把视觉质量问题基本解决，谁也不需要从零训一个视频模型。第二，VPT 和 MineRL 提供了现成的 inverse dynamics model 和可脚本化的 Minecraft 环境，意味着动作标签可以自动生成而不必靠人打游戏。第三，MineDojo 里躺着数千小时无标注实况录像，但里面混着菜单界面、字幕、主播人脸、疯狂甩镜头。</p><p>把这三条串起来，路径几乎是被逼出来的：既然标注数据贵而无标注数据便宜，就先用无标注数据把「世界长什么样、东西怎么动」学进基座，再用少量高质量标注数据把「按键 → 画面变化」这层映射接上去。而 IDM 既然能从视频反推动作，它就不只是数据标注工具，还可以反过来当评测器——用它从生成视频里反推动作、跟输入指令对比，可控性就成了一个数字。GameWorld Score 里的可控性指标基本就是这个思路的直接产物。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>用文本当条件会给世界模型注入语言先验，让模型倾向于「说得通」而不是「看得准」。所以 Matrix-Game 干脆砍掉文本分支，只用一张参考图 + 动作信号，逼模型把几何、运动和交互规律都压进视觉表征里。剩下的问题是数据：动作标签贵，那就把学习拆成「先看懂世界」和「再听懂指令」两段，让 2700 小时无标注视频承担前者、1200 小时脚本化标注视频承担后者。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以「给一张沙漠 biome 的截图，玩家按住前进再向右转视角」为例，系统这样跑：</p><ul><li><strong>数据侧</strong>：从 MineDojo 拿约 6000 小时原始录像，用 TransNet V2 切镜头、FFmpeg 分段，丢掉首尾各 4 帧。三级过滤依次做质量（DOVER）、美学（LAION predictor）、菜单态（IDM 检测无输入帧）、字幕（CRAFT）、人脸（DeepFace）、运动幅度（GMFlow 光流）、相机剧烈旋转（IDM 角度）过滤，留下 2700 小时无标注集。标注数据来自两路：MineRL 里跑 curriculum 引导的 VPT agent，16Hz 抽取逐帧键鼠动作，并把每帧 yaw/pitch 限制在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6741em;"></span><span class="mord">1</span><span class="mord"><span class="mord">5</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6741em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∘</span></span></span></span></span></span></span></span></span></span></span> 以内、关掉 frustum chunk loading 以消除地形突然弹出；另一路是 Unreal Engine 程序化场景，提供无噪声的动作、位姿、交互成败标签。最终得到 1026 小时（33 帧训练）与 1200+ 小时（65 帧训练）两个集合，覆盖 14 个 biome，每个占 4%–7%。</li><li><strong>模型侧</strong>：3D Causal VAE 把视频压到 latent（空间 8 倍、时间 4 倍）。MMDiT 的文本分支被替换成图像分支，参考图经视觉编码器进入。长视频靠 autoregressive 生成：取上一段最后 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">5</span></span></span></span> 帧的 latent，沿 channel 维与噪声 latent 拼接，再拼一个 binary mask 标记哪些帧含有效 motion。</li><li><strong>动作注入</strong>：键盘六个离散动作（up/down/left/right/jump/attack）走 cross-attention；鼠标的连续 pitch 变化量与 latent 拼接后过 MLP 加 temporal self-attention。因为 VAE 有时间压缩，动作序列要用 GameFactory 的 group 技巧对齐到 token。</li><li><strong>训练与推理</strong>：flow matching + rectified flow loss。Stage 1 用无标注数据在 720p 下混合 17/33/65 帧与 16:9、4:3、21:9 训练，再用 870 小时高质量子集精修；Stage 2 接入动作模块，先 33 帧后 65 帧，模型规模 17B。推理时对参考图、motion frames、动作三者都开 CFG，scale=6，50 步采样，flow shift=15。</li></ul><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无独立的形式化推导，训练目标沿用已有范式。Flow matching 的思路是学一个速度场 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，把噪声分布沿直线路径推到数据分布：给定数据 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与噪声 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal" style="margin-right:0.1474em;">N</span><span class="mopen">(</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mclose">)</span></span></span></span>，构造插值 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7651em;vertical-align:-0.15em;"></span><span class="mord mathnormal">t</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，其真实速度恒为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，于是 rectified flow loss 为</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2401em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mpunct mtight">,</span><span class="mord mtight"><span class="mord mathnormal mtight">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3173em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span><span class="mpunct mtight">,</span><span class="mord mtight"><span class="mord mathnormal mtight">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3173em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="minner"><span class="mopen delimcenter" style="top:0em;">∥</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">t</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">c</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mclose delimcenter" style="top:0em;">∥</span></span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.954em;"><span style="top:-3.2029em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span></span></span></span></span></p><p>其中条件 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span> 包含参考图 token、motion frames latent 与动作嵌入。相比 DDPM 逐步去噪，直线路径让采样步数可以显著减少，这也是作者说它收敛与采样效率都更好的原因。训练中以 0.2 概率给 motion frames 和参考图加噪、以 0.25 概率把 motion latent 置零、以 0.1 概率丢弃动作信号，本质上都是把 CFG 的无条件分支训出来，推理时再用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6679em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span></span><span style="top:-3.35em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">~</span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord amsrm">∅</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">s</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">c</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord amsrm">∅</span><span class="mclose">))</span></span></span></span> 放大条件的作用。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>作者把实验组织成四个问题。<strong>整体是否更强</strong>：在 GameWorld Score 上与 OASIS、MineWorld 比，Matrix-Game 在图像质量 0.72、美学 0.49、时序一致性 0.97、运动平滑 0.98、键盘准确率 0.95、鼠标准确率 0.95、物体一致性 0.76、场景一致性 0.93，其中键鼠准确率相对 MineWorld 的 0.86/0.64 提升最明显。<strong>控制粒度够不够细</strong>：Table 3 逐动作看，前进 0.99、右移 0.96、跳跃 0.95，所有键盘动作在 0.88 以上；八个方向的鼠标运动全部在 0.89 以上，而 OASIS 的对角方向低到 0.33。<strong>跨场景是否稳</strong>：在 beach/desert/forest/hills/icy/mushroom/plains/river 八个 biome 上分别画雷达图，优势在所有场景保持。<strong>长视频能否续</strong>：多段 autoregressive 生成在段与段之间没有出现几何错位。</p><p>作者还做了两组独立的双盲人工评测，Matrix-Game 在整体质量、可控性、视觉质量、时序一致性上的胜率分别是 96.30%、93.76%、98.23%、89.56%，与自动指标方向一致，这被作者用来论证 GameWorld Score 是人类判断的可靠代理。失败案例也给了两类：罕见 biome 下时序一致性崩掉，以及角色直接穿过树叶——后者说明物理交互仍是弱项。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：Matrix-Game 用两阶段训练把无标注游戏视频和动作标注数据的作用分开，前者学世界结构、后者学控制映射。模型砍掉文本条件，只以单张参考图 + 键鼠动作驱动 17B MMDiT，在 3D Causal VAE 的 latent 空间用 flow matching 训练。长视频靠把上一段末 5 帧作为 motion context 自回归续写，并用加噪与 motion-CFG 抑制误差累积。配套的 GameWorld Score 用 IDM 反推动作来量化可控性、用对称相机运动的回归误差量化场景一致性。结果是控制精度和物理一致性相对 OASIS、MineWorld 有明显提升，但物理交互（如穿模）仍未解决。</p><p><strong>3 句话版</strong>：把「看懂世界」和「听懂指令」拆成两个训练阶段，用便宜的无标注视频扛前者、用脚本化生成的标注数据扛后者。图像条件替代文本条件，动作通过 cross-attention 与 temporal attention 注入 DiT。IDM 既是标注器也是评测器，让可控性第一次变成可比较的数字。</p><p><strong>1 句话版</strong>：数据配方 + 规模化 + 一个把可控性变成数字的 benchmark，共同把 Minecraft 世界模型推到了可用的控制精度。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最要命的假设是：<strong>IDM 从生成视频里反推出的动作，可以当作「模型是否真的执行了指令」的可信标签</strong>。整个可控性论证——GameWorld Score 的键鼠准确率、Table 3 的逐动作精度——全部建立在这上面。论文给出的证据是 IDM 在 1962 小时真实 gameplay 上键盘准确率 90.6%、鼠标回归 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.97</span></span></span></span>。问题在于这个数字是在<strong>真实视频</strong>上测的，而它被用来评判<strong>生成视频</strong>。生成视频有自己的伪影分布，IDM 在其上的行为没有被验证。更麻烦的是循环依赖：训练数据的动作标签也是 IDM 打的（VPT agent 轨迹、菜单过滤、相机过滤都用 IDM），所以模型可能学到的是「让 IDM 满意的画面变化」，而不是「物理上正确的位移」。作者没有报告 IDM 在生成视频上的校准结果，这是证据链里缺的一环。人工双盲评测部分缓解了这一点，但人评的是相对偏好，不是绝对的动作执行正确性。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要复现 17B 模型。一周可做的验证目标是「IDM 评测是否可信」：</p><ol><li>取 OASIS 与 MineWorld 的开源权重，各生成 200 条带已知动作序列的短视频。</li><li>用两个不同来源的 IDM（VPT 原版 + 自己在 MineRL 数据上重训一个结构不同的）分别反推动作，计算两者对同一批生成视频的一致率。</li><li>同时找 5 位标注者对其中 50 条做人工动作判读，得到人类标签。</li><li>测量：IDM-vs-人类的一致率在真实视频与生成视频上分别是多少，差距有多大。</li></ol><p>若生成视频上 IDM-人类一致率相对真实视频掉超过 10 个百分点，或两个 IDM 之间分歧显著，则 GameWorld Score 的可控性排序需要打折扣；若两者都稳定，则该指标可以放心使用。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>针对场景一致性指标设计攻击。GameWorld Score 的 Scenario Consistency 用「镜头往一个方向转出去再原路转回来，比较对应帧的 MSE，允许 4 像素偏移」。一个只会做<strong>局部外推 + 强时序平滑</strong>、完全不记忆场景的模型，只要在回程时把画面平滑地插值回去，就可能拿到不错的分数——因为 Minecraft 的 biome 纹理高度自相似，草地转回来还是草地。真正的反例是：在场景中放一个显著且唯一的地标（比如一座村庄的钟楼），执行「左转 180° 再右转 180°」，检查钟楼是否回到原位、形状是否一致。可以预测的失败条件是，Matrix-Game 的 motion context 只有 5 帧，视场外的信息在 latent 里没有任何显式存储，一旦地标离开视野的时间超过 5 帧所覆盖的时间跨度，模型就没有机制把它取回来。作者自己在 future work 里提到要加 memory 机制，等于承认了这一点。这个实验若成立，说明 0.93 的场景一致性主要反映的是纹理统计的自相似性，而不是真正的空间记忆。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：Matrix-Game 把可控性做到了 0.95，但物理交互（穿模、碰撞）仍然失败，而 GameWorld Score 也没有指标能抓住这类错误——它测的是几何一致性和外观一致性，不测「这个动作在物理上是否被允许」。</p><p><strong>新的 framing</strong>：不要再把世界模型当成「条件视频生成器」来评，而是把它当成<strong>可证伪的环境模拟器</strong>来评。借鉴程序验证与 model checking 的工具：在 Minecraft 引擎里为每条轨迹自动抽取一组<strong>时序逻辑断言</strong>（例如「若前方一格是实心方块，则 forward 不应改变 agent 的 x/z 坐标」「若脚下无支撑，则 y 坐标必须单调下降」），这些断言可以从游戏引擎状态零成本导出。然后用 SLAM 或单目深度从生成视频里恢复 agent 轨迹，检查断言违反率。这把「物理理解」从模糊的视觉一致性变成了布尔判定。</p><p><strong>第一个实验</strong>：只做「碰撞」一条断言。构造 300 个初始帧，agent 正对一堵石墙，指令固定为持续 forward。用 DROID-SLAM 估计生成视频里的相机位移，统计有多少条视频里位移穿过了墙面所在平面。在 OASIS、MineWorld、Matrix-Game 上分别测。若三者的违反率都在同一量级，说明现有的规模化路线并没有带来真正的物理约束学习，这会直接推动把断言违反率当作训练信号（例如作为 reward 做后训练）的下一步工作。</p>',40)])])}const d=a(e,[["render",l]]);export{g as __pageData,d as default};
